-- PGC: dados de demonstração para o banco LOCAL (Supabase CLI: "npm run banco:zerar" roda este arquivo).
-- Tudo aqui é fictício: Ana Souza, seis colegas com apelidos inventados e uma conta nova vazia.
-- NUNCA rode este arquivo no banco da nuvem. A senha de demonstração está em docs/BANCO-LOCAL.md.
-- Datas relativas a hoje (horário de Brasília): rodar de novo amanhã continua mostrando "estudou hoje".
-- Montado com as regras do próprio app (shared/regras): questões conferidas por prepararParaGravar, textos
-- divididos por prepararMaterial, respostas coerentes com o embaralhamento (corrigir) e cartões do FSRS (revisar).
-- Ana libera tudo, menos a Prova (respondeu 5 tipos de questão; a Prova pede 6).

-- Funções de apoio (só nesta conexão).
create function pg_temp.em(dias int, hora text) returns timestamptz language sql stable as $$
  select (((now() at time zone 'America/Sao_Paulo')::date - dias) + hora::time) at time zone 'America/Sao_Paulo'
$$;
create function pg_temp.hoje() returns date language sql stable as $$
  select (now() at time zone 'America/Sao_Paulo')::date
$$;
-- Dia do FSRS: dias desde 1970 no horário de Brasília (o mesmo de diaDeBrasilia() em shared/regras/revisoes.js).
create function pg_temp.dia_num(dias int) returns int language sql stable as $$
  select floor((extract(epoch from now()) - 10800) / 86400)::int - dias
$$;
create temp table senha_demo as select extensions.crypt('pgc.local.2026', extensions.gen_salt('bf')) as hash;

-- 1. Contas (entram pelo e-mail e pela senha de demonstração; o perfil nasce pelo gatilho criar_perfil) ---------
insert into auth.users (instance_id, id, aud, role, email, encrypted_password, email_confirmed_at, confirmation_token, recovery_token,
  email_change_token_new, email_change, email_change_token_current, phone_change, phone_change_token, reauthentication_token,
  raw_app_meta_data, raw_user_meta_data, created_at, updated_at, last_sign_in_at, is_sso_user, is_anonymous)
select '00000000-0000-0000-0000-000000000000', u.id, 'authenticated', 'authenticated', u.email, (select hash from senha_demo), now(),
  '', '', '', '', '', '', '', '', '{"provider": "email", "providers": ["email"]}'::jsonb, u.meta, u.criado, now(), now(), false, false
from (values
  ('a0a0a0a0-0000-4000-8000-000000000001'::uuid, 'ana@pgc.local', '{"nome_exibicao":"Ana Souza","apelido":"ana.estuda","ritmo":"normal","objetivo":"enem","areas_interesse":["matematica","natureza","humanas","programacao"],"privacidade_aceita":"true"}'::jsonb, now() - interval '45 days'),
