insert into public.material_trechos (id, usuario_id, versao_id, ordem, pagina, tipo, texto, usar_em_questoes, assunto_id) values
  ('33000000-0000-4000-8000-000000001001', 'a0a0a0a0-0000-4000-8000-000000000001', '31000000-0000-4000-8000-000000000001', 1, 1, 'titulo', 'Funções do 1º grau', true, '11000000-0000-4000-8000-000000000011'),
  ('33000000-0000-4000-8000-000000001002', 'a0a0a0a0-0000-4000-8000-000000000001', '31000000-0000-4000-8000-000000000001', 2, 1, 'texto', 'Uma função do 1º grau tem a forma f(x) = ax + b, com a diferente de zero. O número a é o coeficiente angular e diz quanto f(x) muda quando x aumenta uma unidade. O número b é o coeficiente linear e mostra onde a reta corta o eixo y.', true, '11000000-0000-4000-8000-000000000011'),
  ('33000000-0000-4000-8000-000000001003', 'a0a0a0a0-0000-4000-8000-000000000001', '31000000-0000-4000-8000-000000000001', 3, 1, 'titulo', 'Gráfico', true, '11000000-0000-4000-8000-000000000011'),
  ('33000000-0000-4000-8000-000000001004', 'a0a0a0a0-0000-4000-8000-000000000001', '31000000-0000-4000-8000-000000000001', 4, 1, 'texto', 'O gráfico de uma função do 1º grau é uma reta. Se a é positivo, a reta sobe da esquerda para a direita e a função é crescente. Se a é negativo, a reta desce e a função é decrescente.', true, '11000000-0000-4000-8000-000000000011'),
  ('33000000-0000-4000-8000-000000001005', 'a0a0a0a0-0000-4000-8000-000000000001', '31000000-0000-4000-8000-000000000001', 5, 1, 'titulo', 'Raiz da função', true, '11000000-0000-4000-8000-000000000011'),
  ('33000000-0000-4000-8000-000000001006', 'a0a0a0a0-0000-4000-8000-000000000001', '31000000-0000-4000-8000-000000000001', 6, 1, 'texto', 'A raiz é o valor de x que deixa f(x) igual a zero. Para achar a raiz, resolva ax + b = 0. Por exemplo, em f(x) = 3x - 12, temos 3x = 12 e x = 4. No gráfico, a raiz é o ponto em que a reta corta o eixo x.', true, '11000000-0000-4000-8000-000000000011'),
  ('33000000-0000-4000-8000-000000001007', 'a0a0a0a0-0000-4000-8000-000000000001', '31000000-0000-4000-8000-000000000001', 7, 1, 'titulo', 'Exemplos do dia a dia', true, '11000000-0000-4000-8000-000000000011'),
  ('33000000-0000-4000-8000-000000001008', 'a0a0a0a0-0000-4000-8000-000000000001', '31000000-0000-4000-8000-000000000001', 8, 1, 'lista', '- Uma corrida de táxi com bandeirada de R$ 5,00 e R$ 2,50 por quilômetro: f(x) = 2,5x + 5.
- Um plano de celular de R$ 30,00 por mês e R$ 0,10 por mensagem extra: f(x) = 0,1x + 30.', true, '11000000-0000-4000-8000-000000000011'),
  ('33000000-0000-4000-8000-000000001009', 'a0a0a0a0-0000-4000-8000-000000000001', '31000000-0000-4000-8000-000000000001', 9, 1, 'texto', 'Coeficiente angular é a taxa de variação da função. Coeficiente linear é o valor da função quando x vale zero.', true, '11000000-0000-4000-8000-000000000011');
