insert into public.material_trechos (id, usuario_id, versao_id, ordem, pagina, tipo, texto, usar_em_questoes, assunto_id) values
  ('33000000-0000-4000-8000-000000003001', 'a0a0a0a0-0000-4000-8000-000000000001', '31000000-0000-4000-8000-000000000003', 1, 1, 'titulo', 'Organelas da célula', true, '11000000-0000-4000-8000-000000000021'),
  ('33000000-0000-4000-8000-000000003002', 'a0a0a0a0-0000-4000-8000-000000000001', '31000000-0000-4000-8000-000000000003', 2, 1, 'texto', 'As organelas são estruturas dentro da célula, cada uma com uma função. Elas ficam no citoplasma, o líquido que preenche a célula.', true, '11000000-0000-4000-8000-000000000021'),
  ('33000000-0000-4000-8000-000000003003', 'a0a0a0a0-0000-4000-8000-000000000001', '31000000-0000-4000-8000-000000000003', 3, 1, 'titulo', 'Principais organelas', true, '11000000-0000-4000-8000-000000000021'),
  ('33000000-0000-4000-8000-000000003004', 'a0a0a0a0-0000-4000-8000-000000000001', '31000000-0000-4000-8000-000000000003', 4, 1, 'lista', '- Mitocôndria: faz a respiração celular e libera energia.
- Ribossomo: produz proteínas a partir das instruções do RNA.
- Complexo de Golgi: guarda, modifica e envia substâncias.
- Lisossomo: faz a digestão dentro da célula.
- Cloroplasto: faz a fotossíntese e existe nas células vegetais.', true, '11000000-0000-4000-8000-000000000021'),
  ('33000000-0000-4000-8000-000000003005', 'a0a0a0a0-0000-4000-8000-000000000001', '31000000-0000-4000-8000-000000000003', 5, 1, 'titulo', 'Célula animal e célula vegetal', true, '11000000-0000-4000-8000-000000000021'),
  ('33000000-0000-4000-8000-000000003006', 'a0a0a0a0-0000-4000-8000-000000000001', '31000000-0000-4000-8000-000000000003', 6, 1, 'texto', 'As duas têm membrana plasmática, citoplasma e núcleo. A célula vegetal tem ainda parede celular, cloroplastos e um vacúolo grande.', true, '11000000-0000-4000-8000-000000000021'),
  ('33000000-0000-4000-8000-000000003007', 'a0a0a0a0-0000-4000-8000-000000000001', '31000000-0000-4000-8000-000000000003', 7, 1, 'texto', 'Osmose é a passagem de água através de uma membrana semipermeável.', true, '11000000-0000-4000-8000-000000000021');
