  ('c0c0c0c0-0000-4000-8000-000000000005'::uuid, 30, '17:30', 0.42, 0, 41),
  ('c0c0c0c0-0000-4000-8000-000000000006'::uuid, 28, '16:50', 0.3, 0, 30)
) as c(id, base, hora, chance, de, ate)
cross join generate_series(0, 41) as d
cross join (values ('respostas'), ('conclusao')) as m(motivo)
where d between c.de and c.ate and abs(hashtext(c.id::text || 'dia' || d::text)) % 100 < c.chance * 100;

drop table senha_demo;
